// --- SUPERFICIE DI GENERE 2 (Buchi allargati) ---
// Utilizza la fusione morbida (smooth min) di due tori.

// 1. Parametri collegati ai tuoi slider (A, B, C)
float rMain = A > 0.0 ? A : 0.8;        // Raggio principale dell'anello
// HO MODIFICATO I DEFAULT QUI SOTTO:
float rTube = B > 0.0 ? B : 0.12;       // Spessore del tubo ridotto (prima era 0.25)
float smoothFactor = C > 0.0 ? C : 0.2; // Fusione meno invasiva (prima era 0.4)

// 2. Animazione automatica collegata al tempo 't'
// Fa "respirare" la distanza tra i due buchi nel tempo
float offset = 0.8 + 0.2 * sin(t * 2.0); 

// 3. Calcola le coordinate dei due tori traslati lungo l'asse X
vec3 p1 = p - vec3(-offset, 0.0, 0.0);
vec3 p2 = p - vec3(offset, 0.0, 0.0);

// 4. SDF (Signed Distance Function) esatti per i due tori
float d1 = length(vec2(length(p1.xy) - rMain, p1.z)) - rTube;
float d2 = length(vec2(length(p2.xy) - rMain, p2.z)) - rTube;

// 5. Smooth Minimum: la magia che fonde le due figure come gocce d'acqua
float h = clamp(0.5 + 0.5 * (d2 - d1) / smoothFactor, 0.0, 1.0);
float finalDistance = mix(d2, d1, h) - smoothFactor * h * (1.0 - h);

return finalDistance;

